/* Atomic bounded caller guards and old named-schema/dense-profile compatibility. */
#include "gc/gacha.h"
#include "pr/battle.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
static gc_system sys,before,loaded;static unsigned char saved[524288],mutated[524288];static int checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"gacha host line%d: %s\n",__LINE__,#x);exit(1);}}while(0)
static gc_gacha_ctx setup(void){gc_system_init_defaults(&sys);for(int i=0;i<4;i++)sys.voucher_counts[i]=20;pr_seedstr s;pr_seed_from_ascii(&s,"gacha-host");gc_gacha_ctx ctx={.machine=0,.cursor=4,.timestamp_ms=1791504000000ULL};pr_rng_sow(&ctx.entropy,&s);pr_rng_sow(&ctx.scene_rng,&s);return ctx;}
static void guards(void){for(int i=0;i<18;i++){gc_gacha_ctx c=setup();switch(i){case 0:c.machine=-1;break;case 1:c.machine=3;break;case 2:c.cursor=-1;break;case 3:c.cursor=5;break;case 4:c.timestamp_ms=8640000000000001ULL;break;case 5:c.entropy.s0=NAN;break;case 6:c.scene_rng.s2=1;break;case 7:c.entropy.c=-1;break;case 8:sys.n_eggs=-1;break;case 9:sys.n_eggs=101;break;case 10:sys.n_eggs=75;break;case 11:sys.voucher_counts[3]=0;break;case 12:sys.stats.eggs_pulled=UINT32_MAX;break;case 13:sys.egg_pity[3]=UINT32_MAX;break;case 14:sys.unlock_pity[0]=11;break;case 15:sys.n_eggs=1;sys.eggs[0].species=9001;break;case 16:sys.stats.manaphy_eggs_pulled=UINT32_MAX;break;case 17:c.entropy_draws=UINT32_MAX;break;}
 before=sys;gc_gacha_ctx original=c;gc_gacha_result output={.n=-7},original_out=output;const char *why;CHECK(!gc_system_gacha_pull(&sys,&c,&output,&why));CHECK(!memcmp(&sys,&before,sizeof sys)&&!memcmp(&c,&original,sizeof c)&&!memcmp(&output,&original_out,sizeof output));if(i==10)CHECK(!strcmp(why,"egg:tooManyEggs"));if(i==11)CHECK(!strcmp(why,"egg:notEnoughVouchers"));}
 gc_gacha_ctx c=setup();gc_gacha_result output;before=sys;CHECK(!gc_system_gacha_pull(NULL,&c,&output,NULL));CHECK(!gc_system_gacha_pull(&sys,NULL,&output,NULL));CHECK(!gc_system_gacha_pull(&sys,&c,NULL,NULL)&&!memcmp(&sys,&before,sizeof sys));
 /* Fresh caller cap99 vs unchanged legacy storage cap100. */
 c=setup();c.cursor=0;sys.n_eggs=98;CHECK(gc_system_gacha_pull(&sys,&c,&output,NULL)&&sys.n_eggs==99);before=sys;CHECK(!gc_system_gacha_pull(&sys,&c,&output,NULL)&&!memcmp(&sys,&before,sizeof sys));CHECK(gc_system_add_egg(&sys,1,10,0,1)&&sys.n_eggs==100);CHECK(!gc_system_add_egg(&sys,2,10,0,1));
 for(int cursor=0;cursor<5;cursor++){c=setup();c.cursor=cursor;CHECK(gc_system_gacha_pull(&sys,&c,&output,NULL));int n=(int[]){1,10,5,10,25}[cursor];CHECK(output.n==n&&sys.n_eggs==n&&sys.stats.eggs_pulled==(unsigned)n);bool guarantee=false;for(int i=0;i<n;i++){CHECK(sys.eggs[i].timestamp_ms==c.timestamp_ms&&!sys.eggs[i].override_hidden_ability);guarantee|=sys.eggs[i].tier>=(n==25?2:1);}if(n==10||n==25)CHECK(guarantee);}
}
static uint32_t hashname(const char *s){uint32_t n=2166136261u;for(;*s;s++)n=(n^(unsigned char)*s)*16777619u;return n;}
static uint16_t u16(const unsigned char *p){uint16_t n;memcpy(&n,p,2);return n;}static uint32_t u32(const unsigned char *p){uint32_t n;memcpy(&n,p,4);return n;}static void p32(unsigned char *p,uint32_t n){memcpy(p,&n,4);}
static uint32_t crc(const unsigned char *p,size_t n){uint32_t c=~0u;for(size_t i=0;i<n;i++){c^=p[i];for(int b=0;b<8;b++)c=c>>1^((c&1)?0xedb88320u:0);}return ~c;}
static size_t section_at(size_t n,const char *name){for(size_t at=20;at+8<=n;){uint32_t len=u32(saved+at+4);CHECK(len<=n-at-8);if(u32(saved+at)==hashname(name))return at;at+=8+len;}CHECK(false);return 0;}
static void checksum(size_t n){p32(saved+12,n-20);p32(saved+16,crc(saved+20,n-20));}
static size_t omit(size_t n,const char *section,const char *field){size_t at=section_at(n,section),b=at+8;unsigned nf=u16(saved+b),idx=nf;size_t stride=0,off=0,sz=0;for(unsigned i=0;i<nf;i++){size_t len=u16(saved+b+2+6*i+4);if(u32(saved+b+2+6*i)==hashname(field)){idx=i;off=stride;sz=len;}stride+=len;}CHECK(idx<nf);unsigned count=u16(saved+b+2+6*nf);size_t start=b+4+6*nf,dest=b;uint16_t newnf=nf-1;memcpy(mutated,saved,n);memcpy(mutated+dest,&newnf,2);dest+=2;for(unsigned i=0;i<nf;i++)if(i!=idx){memcpy(mutated+dest,saved+b+2+6*i,6);dest+=6;}memcpy(mutated+dest,&count,2);dest+=2;for(unsigned i=0;i<count;i++){const unsigned char *src=saved+start+i*stride;memcpy(mutated+dest,src,off);dest+=off;memcpy(mutated+dest,src+off+sz,stride-off-sz);dest+=stride-off-sz;}size_t end=at+8+u32(saved+at+4),removed=6+count*sz;CHECK(dest==end-removed);memcpy(mutated+dest,saved+end,n-end);n-=removed;p32(mutated+at+4,u32(saved+at+4)-removed);memcpy(saved,mutated,n);checksum(n);return n;}
static void saves(void){gc_gacha_ctx c=setup();gc_gacha_result out;CHECK(gc_system_gacha_pull(&sys,&c,&out,NULL));for(int i=1;i<=400;i++){sys.dex[i].seen_attr=sys.dex[i].caught_attr=1;sys.dex[i].ribbon_flags=GC_RIBBON_CLASSIC;sys.starters[i].classic_win_count=i;}sys.egg_pity[1]=8;sys.unlock_pity[2]=9;before=sys;size_t n=gc_system_save(&sys,saved,sizeof saved);const char *why;CHECK(n&&gc_system_load(&loaded,saved,n,&why)&&!memcmp(&loaded,&sys,sizeof sys));
 const char *ef[]={"source_type","variant_tier","egg_move_index","is_shiny","override_hidden_ability","timestamp_ms"};for(int i=0;i<6;i++)n=omit(n,"eggs",ef[i]);const char *sf[]={"eggs_pulled","rare_eggs_pulled","epic_eggs_pulled","legendary_eggs_pulled","manaphy_eggs_pulled"};for(int i=0;i<5;i++)n=omit(n,"stats",sf[i]);size_t at=section_at(n,"egg_pity"),bytes=8+u32(saved+at+4);memmove(saved+at,saved+at+bytes,n-at-bytes);n-=bytes;checksum(n);
 CHECK(gc_system_load(&loaded,saved,n,&why));for(int i=0;i<before.n_eggs;i++){before.eggs[i].source_type=before.eggs[i].variant_tier=before.eggs[i].egg_move_index=0;before.eggs[i].is_shiny=before.eggs[i].override_hidden_ability=false;before.eggs[i].timestamp_ms=0;}before.stats.eggs_pulled=before.stats.rare_eggs_pulled=before.stats.epic_eggs_pulled=before.stats.legendary_eggs_pulled=before.stats.manaphy_eggs_pulled=0;memset(before.egg_pity,0,sizeof before.egg_pity);memset(before.unlock_pity,0,sizeof before.unlock_pity);CHECK(!memcmp(&loaded,&before,sizeof before));
}
int main(void){guards();saves();printf("Egg gacha host: %d checks passed\n",checks);return 0;}
